/**
 * Databricks Vector Store Node - Version 1.1
 * Discriminator: mode=retrieve-as-tool
 */


interface Credentials {
  databricksOAuth2Api: CredentialReference;
}

/** Retrieve documents from vector store to be used as tool with AI nodes */
export type LcVectorStoreDatabricksV11RetrieveAsToolParams = {
  /**
   * Canonical RAG mode — declare with the `tool({...})` factory (NOT `vectorStore`) and plug into an AI Agent's `subnodes.tools`. Required subnodes: `embedding`. Set `toolDescription` so the agent knows when to call it.
   * <patterns>
   * <pattern title="retrieve-as-tool mode — RAG via AI Agent (generic, works for any vectorStore* node)">
   * // Substitute the type literal and provider-specific parameters — see the rest of this file
   * // for the exact shape (e.g. pineconeIndex, qdrantCollection, supabaseTableName).
   * const knowledgeBase = tool({
   *   type: '@n8n/n8n-nodes-langchain.vectorStoreXxx',
   *   config: {
   *     name: 'Knowledge Base',
   *     parameters: {
   *       mode: 'retrieve-as-tool',
   *       toolDescription: 'Search the product knowledge base',
   *       // ...provider-specific parameters
   *     },
   *     subnodes: { embedding: embeddingsOpenAi }
   *   }
   * });
   * 
   * const agent = node({
   *   type: '@n8n/n8n-nodes-langchain.agent',
   *   config: {
   *     name: 'Support Agent',
   *     parameters: { promptType: 'define', text: expr('{{ $json.question }}') },
   *     subnodes: { model: openAiModel, tools: [knowledgeBase] }
   *   }
   * });
   * </pattern>
   * </patterns>
   */
  mode: 'retrieve-as-tool';
/**
 * Name of the vector store
 */
    toolName: string | Expression<string>;
/**
 * Explain to the LLM what this tool does, a good, specific description would allow LLMs to produce expected results much more often
 */
    toolDescription: string | Expression<string>;
  databricksIndex?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Column that becomes the document text. Leave empty on a managed-embedding index to use its embedding source column. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @loadOptionsMethod getIndexColumns
 */
    contentColumn?: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Columns to return in document metadata. Defaults to all columns except the key, content and vector columns. Choose from the list, or specify IDs using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getIndexColumns
     * @default []
     */
    metadataColumns?: string[];
    /** Vector ranks purely by semantic similarity. Hybrid adds keyword matching on top, using the search text. Sent as query_type ANN or HYBRID.
     * @default ANN
     */
    searchMode?: 'ANN' | 'HYBRID' | Expression<string>;
    /** Restrict results to rows matching this metadata condition, for example {"source": "handbook"}. Sent as filters_json. Works on STANDARD endpoints only.
     * @default {}
     */
    searchFilterJson?: IDataObject | string | Expression<string>;
  };
/**
 * Number of top results to fetch from vector store
 * @default 4
 */
    topK?: number | Expression<number>;
/**
 * Whether or not to include document metadata
 * @default true
 */
    includeDocumentMetadata?: boolean | Expression<boolean>;
/**
 * Whether or not to rerank results
 * @default false
 */
    useReranker?: boolean | Expression<boolean>;
};

export interface LcVectorStoreDatabricksV11RetrieveAsToolSubnodeConfig {
  embedding: EmbeddingInstance | EmbeddingInstance[];
  /**
   * @displayOptions.show { useReranker: [true] }
   */
  reranker: RerankerInstance;
}

export type LcVectorStoreDatabricksV11RetrieveAsToolNode = {
  type: '@n8n/n8n-nodes-langchain.vectorStoreDatabricks';
  version: 1.1;
  config: NodeConfig<LcVectorStoreDatabricksV11RetrieveAsToolParams> & { credentials?: Credentials } & { subnodes: LcVectorStoreDatabricksV11RetrieveAsToolSubnodeConfig };
};